// 补跑 import-all 中途中止的项目，完成后快照 + 去重报告
import fs from "fs";
import path from "path";
import { spawnSync } from "child_process";

const BASE = path.dirname(new URL(import.meta.url).pathname.replace(/^\//, "").replace(/\//g, path.sep));
if (process.platform === "win32" && BASE.startsWith("\\")) {
  // pathname on win can be /C:/... — normalize
}
const BASE_DIR = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration";
const TMP = process.env.TEMP || "C:\\Users\\ADMINI~1\\AppData\\Local\\Temp";
const PROJECTS = ["苏住房C", "产品2.0", "门户"];
const BATCH = 4;
const GAP = 5000;
const SNAPSHOT = "D:\\repository\\skills\\scripts\\snapshot-openviking-memory.mjs";
const DEDUPE = path.join(BASE_DIR, "scripts", "dedupe-memories-report.mjs");

function runImport(project) {
  const doneFile = path.join(TMP, `done-${project}.json`);
  const args = [path.join(BASE_DIR, "import-to-ov.mjs"), project, `--batch=${BATCH}`, `--gap=${GAP}`];
  if (fs.existsSync(doneFile)) args.push(`--skip=${doneFile}`);
  console.log(`\n========== ${project} ==========`);
  const r = spawnSync(process.execPath, args, { cwd: BASE_DIR, stdio: "inherit", encoding: "utf8" });
  return r.status ?? 1;
}

let fail = 0;
for (const p of PROJECTS) {
  const code = runImport(p);
  if (code !== 0) {
    console.error(`[FAIL] ${p} exit ${code}`);
    fail++;
  }
}

console.log("\n=== 快照 openviking-memory ===");
if (fs.existsSync(SNAPSHOT)) {
  const snap = spawnSync(
    process.execPath,
    [SNAPSHOT, "--commit", "--push", "--reason", "import-all-complete"],
    { cwd: "D:\\repository\\skills", stdio: "inherit", encoding: "utf8" }
  );
  if (snap.status !== 0) fail++;
} else {
  console.warn("missing snapshot script");
  fail++;
}

console.log("\n=== 去重审计报告 ===");
if (fs.existsSync(DEDUPE)) {
  spawnSync(process.execPath, [DEDUPE], { cwd: BASE_DIR, stdio: "inherit", encoding: "utf8" });
} else {
  console.warn("missing dedupe script");
}

process.exit(fail > 0 ? 1 : 0);

