// 只读：扫描 OpenViking memories，输出重复/薄条/葡语目录报告
import fs from "fs";
import path from "path";
import crypto from "crypto";
import os from "os";

const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const OUT = path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\//, "C:/")), "..", "out");
// fix win path from file URL
const OUT_DIR = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration\\out";

const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md")) files.push(p);
  }
}
walk(MEM);

const byBase = new Map();
const byHash = new Map();
const thin = [];
const noFields = [];
const foreignDirs = new Set();
const overview = [];

for (const f of files) {
  const rel = path.relative(MEM, f).replace(/\\/g, "/");
  if (/padrão|estrutura de|projeto de/i.test(rel)) foreignDirs.add(rel.split("/").slice(0, 2).join("/"));
  const raw = fs.readFileSync(f, "utf8");
  const body = raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g, "").trim();
  const base = path.basename(f, ".md").toLowerCase();
  if (!byBase.has(base)) byBase.set(base, []);
  byBase.get(base).push(rel);
  const h = crypto.createHash("sha256").update(body).digest("hex").slice(0, 16);
  if (!byHash.has(h)) byHash.set(h, []);
  byHash.get(h).push(rel);
  if (!raw.includes("MEMORY_FIELDS")) noFields.push(rel);
  if (e.name === ".overview.md" || /^# Entities Overview/m.test(body.slice(0, 120))) overview.push(rel);
  const lines = body.split(/\n/).filter((l) => l.trim() && !l.startsWith("#"));
  if (body.length < 400 && lines.length < 3) thin.push({ rel, len: body.length, lines: lines.length });
}

const dupBase = [...byBase.entries()]
  .filter(([, v]) => v.length > 1 && v[0] !== ".overview.md")
  .filter(([b]) => b !== ".overview")
  .sort((a, b) => b[1].length - a[1].length);
const dupHash = [...byHash.entries()].filter(([, v]) => v.length > 1);

const report = {
  generatedAt: new Date().toISOString(),
  totalMd: files.length,
  duplicateBodyGroups: dupHash.length,
  duplicateBasenameGroups: dupBase.length,
  overviewCards: overview.length,
  missingMemoryFields: noFields.length,
  thinEntries: thin.length,
  foreignDirPrefixes: [...foreignDirs].sort(),
  topBasenameDupes: dupBase.slice(0, 30).map(([name, paths]) => ({ name, count: paths.length, paths })),
  topBodyDupes: dupHash.slice(0, 10).map(([hash, paths]) => ({ hash, count: paths.length, paths })),
  mergeCandidates: dupBase
    .filter(([, paths]) => paths.length === 2 && !paths.every((p) => p.includes(".overview")))
    .slice(0, 50)
    .map(([name, paths]) => ({ name, paths, action: "keep_richest_then_delete_or_merge" })),
};

fs.mkdirSync(OUT_DIR, { recursive: true });
const jsonPath = path.join(OUT_DIR, "dedupe-report.json");
const mdPath = path.join(OUT_DIR, "dedupe-report.md");
fs.writeFileSync(jsonPath, JSON.stringify(report, null, 2), "utf8");

const md = [
  `# OpenViking 记忆去重审计`,
  ``,
  `- 生成: ${report.generatedAt}`,
  `- 总条数: **${report.totalMd}**`,
  `- 正文完全相同: **${report.duplicateBodyGroups}** 组`,
  `- 同名 slug 多路径: **${report.duplicateBasenameGroups}** 组（不含 .overview）`,
  `- Overview 索引卡: **${report.overviewCards}**`,
  `- 缺 MEMORY_FIELDS: **${report.missingMemoryFields}**`,
  `- 偏薄条目: **${report.thinEntries}**`,
  `- 葡语误分类目录: ${report.foreignDirPrefixes.join(", ") || "无"}`,
  ``,
  `## 建议合并（双份 slug）`,
  ...report.mergeCandidates.map((m) => `- **${m.name}**: ${m.paths.join(" | ")}`),
  ``,
  `完整 JSON: dedupe-report.json`,
].join("\n");
fs.writeFileSync(mdPath, md, "utf8");
console.log("Wrote:", jsonPath);
console.log("Wrote:", mdPath);
console.log(
  `summary: md=${report.totalMd} basenameDupes=${report.duplicateBasenameGroups} bodyDupes=${report.duplicateBodyGroups}`
);

